const item = $input.first().json;
return [
  {
    json: { scheduledAt: item.submittedAt ?? new Date().toISOString(), submission: item },
    pairedItem: { item: 0 },
  },
];

function productLink(value) {
  const raw = typeof value === "string" ? value.trim() : "";
  const match =
    /^https:\/\/(?:www\.)?zalando\.ch(\/[a-z0-9/%._~-]+\.html)(\?[^#\s\\]*)?(?:#[^\s\\]*)?$/i.exec(
      raw,
    );
  if (
    !match ||
    raw.length > 2048 ||
    /%(?![a-f\d]{2})/i.test(raw) ||
    /%(?:00|2f|5c)/i.test(match[1]) ||
    match[1].split("/").some((segment) => /^\.{1,2}$/.test(segment.replace(/%2e/gi, ".")))
  ) {
    throw Error("Enter the product page URL from the Swiss Zalando store.");
  }
  return "https://www.zalando.ch" + match[1] + (match[2] ?? "");
}
function chfCents(input) {
  if (typeof input !== "number" && typeof input !== "string") return null;
  const plain = String(input)
    .trim()
    .replace(/[\u00a0\u202f\u2007]/g, " ");
  const grouped = /^\d{1,3}(['\u2019 ])\d{3}(?:\1\d{3})*(?:[.,]\d{1,2})?$/.test(plain);
  const number = grouped ? plain.replace(/['\u2019 ]/g, "") : plain;
  if (!/^\d{1,8}(?:[.,]\d{1,2})?$/.test(number)) return null;
  const [whole, decimal = ""] = number.split(/[.,]/);
  return Number(whole) * 100 + Number(decimal.padEnd(2, "0"));
}
function watchConfig(entry, spreadsheetId, recipient) {
  if (
    !/^[A-Za-z0-9_-]{15,150}$/.test(spreadsheetId) ||
    spreadsheetId === "YOUR_GOOGLE_SPREADSHEET_ID"
  )
    throw Error("Set the Google spreadsheet ID.");
  if (typeof recipient !== "string" || !/^[-a-z0-9._+]+@[-a-z0-9.]+\.[a-z]{2,}$/i.test(recipient))
    throw Error("Set the Gmail recipient.");
  const time = new Date(entry.scheduledAt);
  if (!Number.isFinite(time.getTime()))
    throw Error("The workflow did not receive the trigger timestamp.");
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: "Europe/Zurich",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(time);
  const date = ["year", "month", "day"]
    .map((part) => parts.find((x) => x.type === part).value)
    .join("-");
  let registration = null;
  if (entry.submission) {
    const link = productLink(entry.submission.link),
      threshold = chfCents(entry.submission.price_alert);
    if (threshold === null) throw Error("Enter a CHF threshold with at most two decimal places.");
    registration = { link, threshold };
  }
  return { spreadsheetId, recipient, date, registration };
}
function workbookRanges() {
  return ["'Links'!A1:E", "'Pricing History'!A1:F"];
}

const settings = {
  spreadsheetId: "YOUR_GOOGLE_SPREADSHEET_ID",
  recipient: "",
};
const config = watchConfig($input.first().json, settings.spreadsheetId, settings.recipient);
const read =
  "https://sheets.googleapis.com/v4/spreadsheets/" +
  config.spreadsheetId +
  "/values:batchGet?majorDimension=ROWS&valueRenderOption=UNFORMATTED_VALUE&" +
  workbookRanges()
    .map((r) => "ranges=" + encodeURIComponent(r))
    .join("&");
return [
  {
    json: {
      config,
      read,
      write:
        "https://sheets.googleapis.com/v4/spreadsheets/" +
        config.spreadsheetId +
        "/values:batchUpdate",
    },
    pairedItem: { item: 0 },
  },
];

