function planWorkbook(reply, config) {
  const ranges = reply?.valueRanges;
  if (reply?.spreadsheetId !== config.spreadsheetId || ranges?.length !== 2)
    throw Error("Google Sheets returned the wrong workbook or tabs.");
  const [live, history] = ranges;
  const header = (range, name, fields) => {
    if (
      typeof range?.range !== "string" ||
      range.range.split("!")[0].replace(/^'|'$/g, "") !== name ||
      !Array.isArray(range.values) ||
      fields.some((field, i) => range.values[0]?.[i] !== field)
    ) {
      throw Error("Set the documented headers in the " + name + " tab.");
    }
  };
  header(live, "Links", ["link", "price_alert", "price", "name", "update"]);
  header(history, "Pricing History", ["price", "name", "link", "update", "key", "currency"]);
  const products = [],
    links = new Set();
  for (const [index, row] of live.values.slice(1).entries()) {
    if (!row?.[0]) continue;
    const link = productLink(row[0]),
      threshold = chfCents(row[1]);
    if (threshold === null || links.has(link))
      throw Error("Check for duplicate links or an invalid CHF threshold in Links.");
    links.add(link);
    products.push({ link, threshold, row: index + 2 });
  }
  const historyRows = new Map();
  for (const [index, row] of history.values.slice(1).entries()) {
    const key = row?.[4];
    if (!key) continue;
    if (typeof key !== "string" || historyRows.has(key))
      throw Error("Pricing History contains an invalid or duplicate key.");
    historyRows.set(key, index + 2);
  }
  const change = config.registration;
  let registration = null;
  if (change) {
    const current = products.find((record) => record.link === change.link);
    if (current) current.threshold = change.threshold;
    else products.push({ ...change, row: live.values.length + 1 });
    const row = current?.row ?? live.values.length + 1;
    registration = {
      range: "'Links'!A" + row + ":B" + row,
      values: [[change.link, change.threshold / 100]],
    };
  }
  let next = history.values.length + 1;
  return {
    registration,
    products: products.map((product) => {
      const key = config.date + " | " + product.link;
      return { ...product, key, historyRow: historyRows.get(key) ?? next++ };
    }),
  };
}
function sheetWrite(data, spreadsheetId) {
  return {
    spreadsheetId,
    data,
    valueInputOption: "RAW",
    includeValuesInResponse: true,
    responseValueRenderOption: "UNFORMATTED_VALUE",
  };
}

const response = $input.first().json,
  setup = $("Set the spreadsheet and recipient").first().json;
if (response.statusCode !== 200) throw Error("Google Sheets did not return the tracking workbook.");
const plan = planWorkbook(response.body, setup.config);
const { spreadsheetId: unused, ...request } = sheetWrite(
  plan.registration ? [plan.registration] : [],
  setup.config.spreadsheetId,
);
return [{ json: { plan, write: setup.write, request }, pairedItem: { item: 0 } }];

function checkedSheet(reply, spreadsheetId, data) {
  if (
    reply?.spreadsheetId !== spreadsheetId ||
    !Array.isArray(reply.responses) ||
    reply.responses.length !== data.length
  ) {
    throw Error("Google Sheets did not confirm the intended write.");
  }
  const canonical = (value) =>
    typeof value === "string" ? value.replace(/^'([^']+)'!/, "$1!") : "";
  for (const [index, entry] of data.entries()) {
    const result = reply.responses[index];
    if (
      canonical(result.updatedRange) !== canonical(entry.range) ||
      result.updatedRows !== 1 ||
      JSON.stringify(result.updatedData?.values) !== JSON.stringify(entry.values)
    ) {
      throw Error("Google Sheets did not confirm the values in the intended row.");
    }
  }
}

const response = $input.first().json,
  setup = $("Set the spreadsheet and recipient").first().json,
  plan = $("Plan the workbook rows").first().json.plan;
if (response.statusCode !== 200) throw Error("Google Sheets did not confirm registration.");
checkedSheet(response.body, setup.config.spreadsheetId, [plan.registration]);
return [{ json: { ok: true }, pairedItem: { item: 0 } }];

return $("Plan the workbook rows")
  .first()
  .json.plan.products.map((product) => ({ json: { product }, pairedItem: { item: 0 } }));

