  const [whole, decimal = ""] = number.split(/[.,]/);
  return Number(whole) * 100 + Number(decimal.padEnd(2, "0"));
}
function zalandoObservation(html, statusCode, link) {
  if (statusCode !== 200 || typeof html !== "string") return null;
  const decode = (text) =>
    text.replace(/&(?:amp|quot|lt|gt|apos|nbsp|#(?:x[0-9a-f]+|\d+));/gi, (entity) => {
      const named = {
        "&amp;": "&",
        "&quot;": '"',
        "&lt;": "<",
        "&gt;": ">",
        "&apos;": "'",
        "&nbsp;": " ",
      };
      if (entity[1] !== "#") return named[entity.toLowerCase()];
      const hex = entity[2].toLowerCase() === "x",
        cp = Number.parseInt(entity.slice(hex ? 3 : 2, -1), hex ? 16 : 10);
      return Number.isSafeInteger(cp) && cp > 0 && cp < 0x110000 && (cp < 0xd800 || cp > 0xdfff)
        ? String.fromCodePoint(cp)
        : "";
    });
  const attrs = (tag) => {
    const values = new Map();
    for (const match of tag.matchAll(/([a-z][\w:-]*)\s*=\s*(?:"([^"]*)"|'([^']*)')/gi)) {
      values.set(match[1].toLowerCase(), decode(match[2] ?? match[3]));
    }
    return values;
  };
  const head = /<head(?:\s[^>]*)?>([\s\S]*?)<\/head>/i.exec(html)?.[1] ?? html;
  for (const match of head.matchAll(/<link\b[^>]*>/gi)) {
    const fields = attrs(match[0]);
    if (fields.get("rel")?.toLowerCase() !== "canonical" || !fields.get("href")) continue;
    try {
      if (productLink(fields.get("href")).split("?")[0] !== link.split("?")[0]) return null;
    } catch {
      return null;
    }
  }
  const prices = new Set();
  for (const match of head.matchAll(/<meta\b[^>]*>/gi)) {
    const fields = attrs(match[0]),
      label = fields.get("name") ?? fields.get("property");
    if (label?.toLowerCase() !== "twitter:data1") continue;
    const contents = fields.get("content")?.trim() ?? "";
    const price = /^(?:CHF\s+(.+)|(.+?)\s+CHF)$/i.exec(contents);
    if (!price) continue;
    const amount = chfCents(price[1] ?? price[2]);
    if (amount === null) return null;
    prices.add(amount);
  }
  const title = /<title(?:\s[^>]*)?>([\s\S]*?)<\/title>/i.exec(head)?.[1];
  const name =
    title &&
    decode(title)
      .replace(/\s*[|–-]\s*Zalando(?:\.ch)?\s*$/i, "")
      .trim()
      .replace(/\s+/g, " ");
  if (
    prices.size !== 1 ||
    !name ||
    name.length > 300 ||
    /[\u0000-\u001f]/.test(name) ||
    /^Zalando(?:\.ch)?$/i.test(name)
  )
    return null;
  return { name, price: [...prices][0] };
}
function observationWrites(product, observation, date) {
  const row = product.row,
    history = product.historyRow;
  return [
    {
      range: "'Links'!C" + row + ":E" + row,
      values: [[observation.price / 100, observation.name, date]],
    },
    {
      range: "'Pricing History'!A" + history + ":F" + history,
      values: [[observation.price / 100, observation.name, product.link, date, product.key, "CHF"]],
    },
  ];
}
function priceNotice(product, observation, recipient) {
  if (observation.price > product.threshold) return null;
  return {
    to: recipient,
    subject: "Price reduction: " + observation.name,
    isHtml: false,
    body:
      observation.name +
      "\nCurrent price: CHF " +
      (observation.price / 100).toFixed(2) +
      "\nAlert threshold: CHF " +
      (product.threshold / 100).toFixed(2) +
      "\n\n" +
      product.link,
  };
}
