  }
}

const response = $input.first().json,
  row = $("Read the product title and CHF price").item.json,
  config = $("Set the spreadsheet and recipient").first().json.config;
if (response.statusCode !== 200) throw Error("Google Sheets did not confirm the observation.");
checkedSheet(response.body, config.spreadsheetId, row.data);
return [{ json: { key: row.key, alert: row.alert }, pairedItem: { item: 0 } }];

