  row = $("Reserve the Gmail alert").item.json;
if (row.status !== "pending" || typeof response.id !== "string" || !response.id)
  throw Error("Check Gmail before retrying this alert.");
return [{ json: { key: row.key, messageId: response.id }, pairedItem: { item: 0 } }];
